<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>支付订单</title><link rel="stylesheet" href="/assets/css/style.css"><style>.pay-page{min-height:100vh;background:#f7f8fb;padding:22px 16px 110px}.pay-card{max-width:620px;margin:0 auto;background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:20px;box-shadow:0 12px 34px rgba(15,23,42,.06)}.pay-title{font-size:22px;font-weight:950;margin:0 0 14px}.pay-row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #f1f5f9}.pay-row span{color:#64748b}.pay-row strong{color:#111827}.qr{display:grid;place-items:center;margin:18px 0}.qr img{max-width:260px;border-radius:14px;border:1px solid #e2e8f0}.qr-box{width:min(300px,100%);padding:16px;border:1px solid #e2e8f0;border-radius:16px;background:#f8fafc;text-align:center;word-break:break-all}.qr-box strong{display:block;color:#0f172a;margin-bottom:8px}.qr-box .qr-link{display:block;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:#0f766e;margin-top:8px}.pay-hint{margin:12px 0 0;padding:10px 12px;border-radius:12px;background:#eff6ff;color:#1d4ed8;font-size:13px;line-height:1.7}.note{color:#64748b;line-height:1.8;font-size:13px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.actions .btn{text-decoration:none}</style></head><body><?php require __DIR__ . '/../layouts/topbar.php'; ?><main class="pay-page"><section class="pay-card"><h1 class="pay-title">支付订单</h1><div class="pay-row"><span>订单号</span><strong><?= htmlspecialchars($order['order_no']) ?></strong></div><div class="pay-row"><span>充值</span><strong><?= currency_trim_amount($order['amount']) ?> <?= htmlspecialchars($order['currency_name'] ?: currency_name_by_code((string)$order['currency_code'])) ?></strong></div><div class="pay-row"><span>支付金额</span><strong><?= currency_trim_amount($order['pay_amount'],2) ?> 元</strong></div><div class="pay-row"><span>状态</span><strong><?= $order['status']==='paid'?'已支付':'待支付' ?></strong></div><?php if($payload['mode']==='redirect' && $payload['url']): ?><div class="actions"><a class="btn" href="<?= htmlspecialchars($payload['url']) ?>">前往支付</a><a class="btn btn-light" href="/index.php?path=wallet">返回钱包</a></div><?php elseif($payload['mode']==='qrcode'): ?><?php if($payload['url']): ?><div class="qr"><img src="<?= htmlspecialchars($payload['url']) ?>" alt="收款码"></div><?php endif; ?><p class="note"><?= htmlspecialchars($payload['note']) ?></p><div class="actions"><a class="btn btn-light" href="/index.php?path=wallet">返回钱包</a></div><?php elseif($payload['mode']==='qrcode_text'): ?><?php $alipayAppUrl='alipays://platformapi/startapp?saId=10000007&qrcode=' . rawurlencode((string)$payload['url']); ?><div class="qr"><div class="qr-box"><strong>支付宝扫码支付</strong><span class="qr-link"><?= htmlspecialchars($payload['url']) ?></span><div class="pay-hint">手机端请点“打开支付宝付款”拉起支付宝；电脑端请用支付宝扫码。付款成功后系统会自动回调入账，若回调延迟，返回本页也会主动同步订单状态。</div></div></div><p class="note"><?= htmlspecialchars($payload['note']) ?></p><div class="actions"><a class="btn" href="<?= htmlspecialchars($alipayAppUrl) ?>">打开支付宝付款</a><a class="btn btn-light" href="/index.php?path=payment/order&order_no=<?= urlencode((string)$order['order_no']) ?>">我已支付，刷新状态</a><a class="btn btn-light" href="/index.php?path=wallet">返回钱包</a></div><?php else: ?><p class="note"><?= htmlspecialchars($payload['note']) ?></p><div class="actions"><a class="btn btn-light" href="/index.php?path=wallet">返回钱包</a></div><?php endif; ?></section></main><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?><?php require __DIR__ . '/../layouts/bottom-nav.php'; ?></body></html>
